{
  "decision-map-legend-source-footprints": "WITH overlaps AS (SELECT l.legend_id, s.sheet_id, s.issued, MIN(l.x1, s.x1) - MAX(l.x0, s.x0) AS width, MIN(l.y1, s.y1) - MAX(l.y0, s.y0) AS height FROM legends AS l JOIN sheets AS s ON s.issued <= l.legend_date AND l.denom BETWEEN s.min_denom AND s.max_denom), ranked AS (SELECT legend_id, sheet_id, width * height AS overlap_km2, ROW_NUMBER() OVER (PARTITION BY legend_id ORDER BY width * height DESC, issued DESC, sheet_id COLLATE BINARY ASC) AS rn FROM overlaps WHERE width > 0 AND height > 0) SELECT l.legend_id, r.sheet_id, COALESCE(r.overlap_km2, 0) AS overlap_km2 FROM legends AS l LEFT JOIN ranked AS r ON r.legend_id = l.legend_id AND r.rn = 1 ORDER BY l.legend_id ASC",
  "decision-marginal-volume-rebate-accrual": "WITH depots AS (SELECT depot_code, SUM(signed_units) AS net_units FROM depot_movement WHERE period_code = 'Q3' GROUP BY depot_code), bands AS (SELECT source_id, lower_units, unit_cents, LEAD(lower_units) OVER (ORDER BY lower_units) AS upper_units FROM band_evidence), accrued AS (SELECT d.depot_code, b.lower_units, b.source_id, (MIN(d.net_units, COALESCE(b.upper_units, d.net_units)) - b.lower_units) * b.unit_cents AS cents FROM depots AS d JOIN bands AS b ON d.net_units > b.lower_units) SELECT d.depot_code, d.net_units, COALESCE((SELECT SUM(a.cents) FROM accrued AS a WHERE a.depot_code = d.depot_code), 0) AS earned_cents, COALESCE((SELECT GROUP_CONCAT(source_id, ',') FROM (SELECT a.source_id FROM accrued AS a WHERE a.depot_code = d.depot_code ORDER BY a.lower_units)), '') AS source_ids FROM depots AS d ORDER BY d.depot_code ASC",
  "decision-marked-point-hausdorff-distance": "SELECT MAX((SELECT MIN(ABS(p.x_cm - q.x_cm) + ABS(p.y_cm - q.y_cm)) FROM floor_marks AS q WHERE q.set_name <> p.set_name)) AS hausdorff_cm FROM floor_marks AS p",
  "decision-market-stall-repair-pair": "WITH pairs AS (SELECT a.source_id AS first_source, b.source_id AS second_source, a.stall_count + b.stall_count AS restored_stalls, a.cost_cents + b.cost_cents AS cost_cents, a.crew_minutes + b.crew_minutes AS crew_minutes FROM crew_estimate AS a JOIN crew_estimate AS b ON a.source_id COLLATE BINARY < b.source_id) SELECT p.first_source, p.second_source, p.restored_stalls, p.cost_cents, p.crew_minutes FROM pairs AS p CROSS JOIN closure_limit AS l WHERE p.cost_cents <= l.ceiling_cents AND p.crew_minutes <= l.available_minutes ORDER BY p.restored_stalls DESC, p.cost_cents ASC, p.first_source COLLATE BINARY ASC, p.second_source COLLATE BINARY ASC LIMIT 1"
}
